// Fixed wording for referrals and acknowledgements (FR-14, FR-19, NFR-19, design decisions D11 and Stage 1 Decision 2).
// Reason and urgency are NEVER generated by Itan or typed by the patient: they are carried verbatim from a source
// or shown as MISSING. An acknowledgement means "received, service offered here", never a statement about beds.
export const MISSING = "Not stated by the referring clinician";
export const NOT_CONFIRMED = "Read from a letter but not yet confirmed by the patient";
export const NONE_RECORDED = "None recorded in this record";
export const DISPUTED = "The patient has marked this as disputed";

export const ACK_OFFERED = "Received — service offered here";
export const ACK_NOT_OFFERED = "Received — service not offered here";
export const ACK_DISCLAIMER = "This is not a statement that a bed is available.";

export const SOURCE_LETTER = "Read from the patient's referral letter and confirmed by the patient";
export const SOURCE_PATIENT = "Entered by the patient";
export const sourcePartner = (facility: string | null) => `Sent by ${facility ?? "the referring hospital"}`;

export type AckStatus = "service_offered" | "service_not_offered";
export const ackLabel = (s: AckStatus) => (s === "service_offered" ? ACK_OFFERED : ACK_NOT_OFFERED);
